  (* LPS 727298f3: the launch's extra reserved intervals at the start of the main phase: the
     ledger's split, count and size are the start-up invariant's ([ak_reserved]); each interval
     lies apart from the primary space and from the pointer array because both are mapped
     ([akernel_main_pre]'s third conjunct) and every mapping is apart from the ledger
     ([co_mres]). *)
  Lemma akernel_resx_main : akernel_resx s0 model.
  Proof.
    pose proof akernel_main_pre as P. unfold akernel_pre_d in P. cbv zeta in P.
    destruct P as (_ & _ & K3 & _).
    destruct ak_reserved as (rx & Hr & Hok & Hlen & Hsz).
    pose proof (co_mres _ _ _ _ _ _ _ _ _ _ _ HC) as MR.
    assert (APART : forall e, In e rx -> 0 < bv_unsigned (snd e) -> bv_unsigned (fst e) + bv_unsigned (snd e) <= 2 ^ 47 ->
              forall lo len, (forall x : word, lo <= bv_unsigned x < lo + len -> in_rangesb x (vm_maps VMM) = true) ->
              0 < len ->
              bv_unsigned (fst e) + bv_unsigned (snd e) <= lo \/ lo + len <= bv_unsigned (fst e)).
    { intros e He Hpos Htop lo len COV Hlen0.
      destruct (Z_le_gt_dec (bv_unsigned (fst e) + bv_unsigned (snd e)) lo) as [A1|A1]; [left; exact A1|].
      destruct (Z_le_gt_dec (lo + len) (bv_unsigned (fst e))) as [A2|A2]; [right; exact A2|].
      exfalso.
      pose proof (bv_unsigned_in_range _ (fst e)) as Re. pose proof (bv_unsigned_in_range _ (snd e)) as Rs.
      change (bv_modulus 64) with (2 ^ 64) in Re, Rs.
      set (xz := Z.max lo (bv_unsigned (fst e))).
      assert (Ux : bv_unsigned (Z_to_bv 64 xz) = xz).
      { rewrite Z_to_bv_unsigned. apply bv_wrap_small. change (bv_modulus 64) with (2 ^ 64). unfold xz. lia. }
      assert (Hx : in_rangesb (Z_to_bv 64 xz) (vm_maps VMM) = true) by (apply COV; rewrite Ux; unfold xz; lia).
      unfold in_rangesb in Hx. apply existsb_exists in Hx as [iv [Hiv Hz]].
      unfold zin_rangeb in Hz. rewrite Ux in Hz. apply andb_true_iff in Hz as [Z1 Z2].
      apply Z.leb_le in Z1. apply Z.ltb_lt in Z2.
      pose proof (proj1 (Forall_forall _ _) MR iv Hiv) as MRi.
      assert (HeR : In e (vm_reserved VMM)) by (rewrite Hr; apply in_or_app; right; exact He).
      pose proof (proj1 (Forall_forall _ _) MRi e HeR) as D. destruct D as [D|D]; unfold xz in *; lia. }
    unfold akernel_resx. cbv zeta. exists rx. split; [exact Hr|]. split; [| split].
    - intros e He. pose proof (proj1 (Forall_forall _ _) Hok e He) as (H1 & _ & _ & _ & H5 & H6).
      split; [exact H1|]. split; [exact H5|]. split.
      + assert (COVs : forall x : word, a_sb s0 <= bv_unsigned x < a_sb s0 + (kSpaceSize + kPageSize) ->
                  in_rangesb x (vm_maps VMM) = true)
          by (intros x Hx; apply K3; right; right; left; lia).
        destruct (APART e He H1 H6 _ _ COVs ltac:(unfold kSpaceSize, kPageSize; lia)) as [D|D];
          [left; exact D| right; unfold kPageSize in D; lia].
      + exact (APART e He H1 H6 _ _ (fun x Hx => K3 x (or_intror (or_intror (or_intror (or_introl Hx)))))
                 ltac:(unfold kPtrArrayReserve; lia)).
    - exact Hlen.
    - eapply Z.le_trans; [| exact Hsz]. apply Z.eq_le_incl. clear.
      induction rx as [|x l IH]; [reflexivity| simpl; rewrite IH; reflexivity].
  Qed.

  Theorem akernel_main : akernel s0 model.
  Proof. exact (conj akernel_main_pre akernel_resx_main). Qed.

  Lemma ri_accessible : forall x : word, pm_region_info X <= bv_unsigned x < pm_region_info X + 4096 ->
